def max_product(arr):
    if not arr:
        return 0

    n = len(arr)
    # dp[i] represents the maximum product of increasing subsequence ending at index i
    dp = [1] * n

    # Initialize each position with the element itself
    for i in range(n):
        dp[i] = arr[i]

    # Fill dp array
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:  # increasing condition
                dp[i] = max(dp[i], dp[j] * arr[i])

    # Return the maximum product found
    return max(dp)
